    "text": "Мы, народ штата Сан-Андреас, благодарные Всемогущему Богу за нашу свободу, чтобы закрепить и увековечить ее блага, в целях создания верного и последовательного правительства, принимаем и устанавливаем настоящую конституцию.\nЭтот документ служит руководящим документом штата Сан-Андреас и всех городов, округов и общин, входящих в его состав.\nЕго цель — четко определить полномочия и власть всех правительственных учреждений и фракций, права и привилегии жителей Сан-Андреаса, принципы общественного представительства и процесс, посредством которого новые законы, концепции и идеи могут воплощаться в жизнь.\nПод руководящими документами понимаются все документы, кодексы и законодательные акты, составляющие юридический корпус штата Сан-Андреас.",
