    "title": "Вне зависимости от законодательных актов иных штатов, смертная казнь на территории штата Сан-Андреас не должна существовать. Лицо не может быть подвергнуто наказанию в виде лишения жизни. Обвинительный приговор, который назначает наказание в виде смертной казни не должен исполняться. Верховному суду следует в незамедлительном порядке прекратить действие такого приговора, а судью, который подписал такой приговор, руководствуясь данным разделом, следует отстранить от работы в срок до окончания проверки в отношении этого судьи.",
