    "id": "constitution-glava-i-deklaraciya-prav-razdel-17",
    "category": "Конституция",
    "codeTitle": "Конституция штата San Andreas",
    "articleNumber": "Раздел 17",
    "title": "Раздел 17",
    "text": "(а) Народ Штата Сан Андреас приходит к заключению и объявляет, что принятие комплексных положений и законов, обеспечивающих билль о правах жертв преступлений, включая гарантии в системе уголовного правосудия в целях всесторонней защиты этих прав, является делом особой важности в масштабах Штата. Права потерпевших входят в систему уголовной юстиции, включая не только право на возмещение со стороны правонарушителей финансового ущерба, причиненного в результате уголовных деяний, но также более существенное право на то, что лица, совершающие преступные деяния и наносящие вред невинной жертве, предстанут перед судом и понесут наказание, достаточное для защиты общественной безопасности, что является целью наибольшей важности.\n(b) Реституция. Такая мера является четко определенной целью Народа Штата Сан Андреас, которая состоит в том, что все лица, понесшие ущерб от преступной деятельности, будут иметь право на возмещение причиненного ущерба от лиц, осужденных за преступления. Реституция будет предусмотрена от осужденных лиц в каждом деле, где жертва преступления понесла ущерб и независимо от вынесенного приговора или наложенных санкций, если только не окажется неопровержимых доводов или особых причин против такой меры.\n(с) Защита свидетелей. Каждый, кто определен в соответствующем законе, обладает неоспоримым правом на участие в программе защиты свидетелей, если иное прямо не установлено законом. Лицо должно добровольно дать согласие для участия в программе защиты свидетелей.",
    "penalty": "Нормативное положение Конституции.",
    "section": "",
    "chapter": "Глава I. Декларация прав",
