    "codeTitle": "Конституция штата San Andreas",
    "articleNumber": "Раздел 3",
    "title": "В Штате Сан-Андреас имеется единственный Апелляционный суд, который действует на всей территории судебного округа Сан-Андреас. В состав апелляционного суда входят апелляционные судьи, их количество устанавливается Председателем Верховного суда.",
    "text": "В Штате Сан-Андреас имеется единственный Апелляционный суд, который действует на всей территории судебного округа Сан-Андреас. В состав апелляционного суда входят апелляционные судьи, их количество устанавливается Председателем Верховного суда.",
