    "text": "Пересмотр Конституции штата Сан-Андреас или рассмотрение поправки в конституцию штата Сан-Андреас осуществляется через голосование на заседании Сената штата Сан-Андреас, проект должен одобряться 2/3 сенаторов, учитывая голоса только присутствующих сенаторов, слушание Сената должно быть открытым.",
