    "articleNumber": "Статья 1.1",
    "title": "Задачи Уголовного кодекса Штата Сан-Андреас.",
    "text": "1. Задачами настоящего Кодекса являются: охрана прав и свобод человека и гражданина, собственности, общественного порядка и общественной безопасности, окружающей среды, конституционного строя Штата Сан-Андреас от преступных посягательств, обеспечение мира и безопасности человечества, а также предупреждение преступлений.\n2. Для осуществления этих задач настоящий Кодекс устанавливает основание и принципы уголовной ответственности, определяет, какие опасные для личности, общества или государства деяния признаются преступлениями, и устанавливает виды наказаний и иные меры уголовно-правового характера за совершение преступлений.",
    "penalty": "Наказание не указано в тексте статьи.",
    "section": "Раздел I. Уголовный закон",
