    "category": "Уголовный кодекс",
    "codeTitle": "Уголовный кодекс штата San-Andreas",
    "articleNumber": "Статья 2.1",
    "title": "Рецидив преступлений",
    "text": "1. Рецидивом преступлений признается совершение умышленного преступления лицом, имеющим судимость за ранее совершенное умышленное преступление.\n2. Рецидив преступлений влечет более строгое наказание на основании и в пределах, предусмотренных настоящим Кодексом, а также иные последствия, предусмотренные законодательством Штата Сан-Андреас.",
