    "text": "1. Лицо освобождается от уголовной ответственности, если со дня совершения преступления прошло 25 лет (( 25 дней )).\n2. К лицам, совершившим преступления, предусмотренные главой 14, статьями 6.1, 6.2, 6.3, 6.4, 7.1, 8.1, 12.1, 12.1.1, 12.1.2, 12.2, 12.3, 12.4, 12.5, 15.1, 15.1.1, 16.1, 16.2, 16.4, 16.10, 17.1 настоящего Кодекса, сроки давности не применяются.\n3. К лицам, находящимся в Федеральном розыске как по решению суда, так и по ордеру Генеральной Прокуратуры, сроки давности не применяются.\n4. Сотрудники LSPD/LSCSD/FIB/USSS могут установить уровень боло-розыска в диапазоне от ★ до ★★★★★ за нарушение Уголовного Кодекса.\n5. По решению суда или ордеру Генеральной Прокуратуры гражданину может быть объявлен уровень боло-розыска в размере ★–★★★★★ за нарушение Уголовного Кодекса.\n6. Сроки давности исчисляются со дня совершения преступления и до момента вступления приговора / решения об аресте в законную силу. В случае совершения лицом нового преступления сроки давности по каждому преступлению исчисляются самостоятельно.",
    "penalty": "2. К лицам, совершившим преступления, предусмотренные главой 14, статьями 6.1, 6.2, 6.3, 6.4, 7.1, 8.1, 12.1, 12.1.1, 12.1.2, 12.2, 12.3, 12.4, 12.5, 15.1, 15.1.1, 16.1, 16.2, 16.4, 16.10, 17.1 настоящего Кодекса, сроки давности не применяются.",
