    "text": "1. Найденные наркотические вещества в ходе обыска сотрудниками гос. структуры в количестве до 3 грамм (включительно), изымаются без привлечения к уголовной ответственности.\n2. В случае нахождения у гражданина более 3 грамм наркотических веществ, несёт за собой уголовную ответственность статьи 13.2.\n3. В случае нахождения у гражданина более 3 грамм \"Семена Green\", несёт за собой уголовную ответственность статьи 13.2.\n4. Найденные вещества \"Семена Green\" в ходе обыска сотрудниками гос. структуры в количество до 3 грамм (включительно), являются легальными без привлечения к уголовной ответственности.\n5. Один \"Куст Green\" приравнивается к 5-ти граммам наркотических веществ.\n6. Одно \"\"Одно семечко Green\" приравнивается к 2-м граммам наркотических средств.\n7. Если у задержанного при обыске было найдено несколько видов наркотических веществ, то статья ч.1 и ч.3 ст. 5.13 настоящего закона неприменимы.\nПримечание: Вес разных видов наркотических веществ складывается и в соответствии с этим применяется статья из 13 главы УК.",
