    "text": "1. ★★★ Кража, то есть тайное хищение чужого имущества, стоимостью свыше $15.000.\nНаказание: до 30 месяцев лишения свободы.\n2. ★★★★ Кража, совершенная:\nа) группой лиц по предварительному сговору;\nб) с незаконным проникновением в помещение либо иное хранилище;\nв) с причинением значительного ущерба гражданину;\nг) из одежды, сумки или другой ручной клади, находившихся при потерпевшем.\nНаказание: до 40 месяцев лишения свободы с созданием записи о судимости.\nПримечание 1 Под хищением в статьях настоящего Кодекса понимаются совершенные с корыстной целью противоправные безвозмездное изъятие и (или) обращение чужого имущества в пользу виновного или других лиц, причинившие ущерб собственнику или иному владельцу этого имущества.\nПримечание 2 Под помещением в статьях настоящей главы понимаются строения и сооружения независимо от форм собственности, предназначенные для временного нахождения людей или размещения материальных ценностей в производственных или иных служебных целях.\nПримечание 3 Под хранилищем в статьях настоящей главы понимаются хозяйственные помещения, обособленные от жилых построек, участки территории, трубопроводы, иные сооружения независимо от форм собственности, которые предназначены для постоянного или временного хранения материальных ценностей.",
    "penalty": "Наказание: до 30 месяцев лишения свободы.",
