    "text": "1. Использование должностным лицом своих полномочий вопреки интересам службы, если это деяние повлекло существенное нарушение прав и законных интересов граждан, организаций или государства.\nНаказание: штраф в размере от $50.000 до $100.000 либо до 50 месяцев лишения свободы с созданием записи о судимости.\n2. Использование должностным лицом полномочий для вмешательства или воспрепятствования процессу задержания, ареста либо судебного разбирательства.\nПояснение: под вмешательством в работу сотрудников другой организации понимается вербальная и/или невербальная помеха проведению процессуальных действий сотрудникам других организаций.\nНаказание: штраф в размере от $40.000 до $90.000 либо до 50 месяцев лишения свободы с созданием записи о судимости.\n3. Те же деяния, совершённые сотрудником органа, уполномоченного расследовать должностные преступления.\nНаказание: до 50 месяцев лишения свободы с созданием записи о судимости.\nПримечание 1. Должностными лицами в статьях настоящей главы признаются лица, постоянно, временно или по специальному полномочию осуществляющие функции представителя власти либо выполняющие организационно-распорядительные, административно-хозяйственные функции в государственных органах, органах местного самоуправления, государственных и муниципальных учреждениях, государственных внебюджетных фондах, государственных корпорациях, государственных компаниях, публично-правовых компаниях, на государственных и муниципальных унитарных предприятиях, в хозяйственных обществах.",
