    "text": "1. ★★★★ Вмешательство в деятельность суда в целях воспрепятствования осуществлению правосудия.\nНаказание: до 40 месяцев лишения свободы с созданием записи о судимости.\n2. ★★★★ Вмешательство в деятельность прокурора или следователя, направленное на препятствие объективному расследованию дела.\nНаказание: до 40 месяцев лишения свободы с созданием записи о судимости.\n3. ★★★★ Те же действия, совершённые с использованием служебного положения.\nНаказание: до 40 месяцев лишения свободы с созданием записи о судимости.\n4. ★★★★ Вмешательство в законную деятельность адвоката, повлекшее причинение существенного вреда правам и интересам граждан или организаций.\nНаказание: до 40 месяцев лишения свободы с созданием записи о судимости.\n5. ★★★ Неуважение к суду — нарушение порядка во время заседания или неявка без уважительных причин.\nНаказание: до 30 месяцев лишения свободы с созданием записи о судимости либо штраф в размере от $15.000 до $45.000\n6. ★★★★ Воспрепятствование адвокатской деятельности, выразившееся в незаконном ограничении доступа адвоката к доверителю, отказе в предоставлении информации, необходимой для защиты, или ином умышленном создании препятствий для осуществления защиты.\nНаказание: до 40 месяцев лишения свободы с созданием записи о судимости.",
    "penalty": "Наказание: до 40 месяцев лишения свободы с созданием записи о судимости.",
