    "id": "procedure-19",
    "category": "Процессуальный кодекс",
    "codeTitle": "Процессуальный кодекс штата San-Andreas",
    "articleNumber": "Статья 19",
    "title": "Уведомление о задержании",
    "text": "1. В случае если известно, что задержанный является государственным служащим, сотрудник, проводивший задержание, обязан вызвать начальство задержанного и сотрудника прокуратуры штата Сан-Андреас. На время ожидания ответа указанных лиц, время задержания замораживается, но не более, чем на 15 минут;\nПримечание: В случае принятия вызова прокурором вследствие звонка на горячую линию Правительства, время задержания замораживается до его приезда. В случае, если сотрудник, проводящий задержание, не получил ответа от сотрудника прокуратуры в течении 10 минут, то сотрудник, проводящий задержание, обязан отпустить задержанного и передать видеофиксацию правонарушения задержанного в прокуратуру для дальнейшего разбирательства.\nПримечание 2: В случае невозможности прибытия начальства задержанного, прокурор или лицо, производящее задержание, обязано в кратчайшие сроки уведомить начальство задержанного о задержании подчинённого. В случае подтверждения вины подчинённого, начальство по первому требованию обязуется прекратить с ним трудовые отношения.\nПримечание 3: Признание факта принадлежности задержанного к государственным органам может быть только путем идентификации его отношения к государственным органам через наличие бейджика, удостоверения, иного идентификационного знака, подтверждающего принадлежность к государственным органам, или подтверждения его личности через базу данных штата Сан-Андреас.\nПримечание 4: В случае, если у сотрудника, который проводит задержание нет доступа к рации департамента, он обязан запросить начальство, используя служебную рацию, и дождаться подтверждения запроса от сотрудников, имеющих доступ к рации департамента либо вызвать прокурора через телефон путем звонка на горячую линию Правительства. На время ожидания ответа от сотрудников время ожидания продлевается.\n2. При приезде начальства задержанного и сотрудника прокуратуры штата Сан-Андреас, сотрудником, осуществившим задержание, должны быть представлены доказательства совершения правонарушения задержанным сотруднику прокуратуры штата Сан-Андреас и начальству задержанного.\nИсключение: задержание лица на основании ордеров и иных нормативных документов.\n3. Сотрудник прокуратуры дает оценку правомерности задержания, устанавливает наличие противоправного деяния в действии (или противоправного бездействия) задержанного, а также устанавливает соразмерность избранной санкции по отношению к действиям задержанного. В случае, если сотрудник прокуратуры штата не признает наличия противоправного деяния в действии (или противоправного бездействии) задержанного или не согласен с решением сотрудника, осуществляющего задержание, задержанный сотрудник подлежит освобождению. Сотрудник, проводивший задержание, имеет право подать обращение в прокуратуру штата Сан-Андреас.\nПримечание: В случае, если сотрудник прокуратуры признает наличие преступного деяния в действии (или преступном бездействии) задержанного и если в качестве наказания определено лишение свободы, начальство задержанного обязано прекратить с задержанным трудовые отношения. В случае назначения наказания в виде штрафа/отсутствия запрета на работу в государственных организациях в диспозиции статьи, прекращение трудовых отношений с задержанным не является обязательным, и решение об увольнении остается на усмотрение работодателя или сотрудника прокуратуры.\nИсключение: Процедура задержания и последующего ареста лица осуществляется на основании официального ордера.",
    "penalty": "Примечание 2: В случае невозможности прибытия начальства задержанного, прокурор или лицо, производящее задержание, обязано в кратчайшие сроки уведомить начальство задержанного о задержании подчинённого. В случае подтверждения вины подчинённого, начальство по первому требованию обязуется прекратить с ним трудовые отношения.",
    "section": "Раздел III. Меры процессуального принуждения",
    "chapter": "Глава III. Процесс задержания",
