    "id": "procedure-22",
    "category": "Процессуальный кодекс",
    "codeTitle": "Процессуальный кодекс штата San-Andreas",
    "articleNumber": "Статья 22",
    "title": "Права задерживаемого",
    "text": "1. У подозреваемого имеются следующие права:\nа) Подозреваемый имеет право на один телефонный звонок в присутствии сотрудника, до начала процесса ареста, сотрудник обязан предоставить телефонный звонок задержанному по его запросу. Длительность звонка не должна превышать 2-х минут;\nб) Подозреваемый имеет право на адвоката (государственного или частного);\nв) Подозреваемый имеет право сохранять молчание;\nг) Подозреваемый имеет право возбуждать ходатайства, а также заявлять отводы.",
    "penalty": "а) Подозреваемый имеет право на один телефонный звонок в присутствии сотрудника, до начала процесса ареста, сотрудник обязан предоставить телефонный звонок задержанному по его запросу. Длительность звонка не должна превышать 2-х минут;",
    "section": "Раздел III. Меры процессуального принуждения",
