    "id": "procedure-52-5",
    "category": "Процессуальный кодекс",
    "codeTitle": "Процессуальный кодекс штата San-Andreas",
    "articleNumber": "Статья 52.5",
    "title": "Возбуждение дела",
    "text": "ч. 1. Возбуждение дела и производство по нему регулируются гл. 15 настоящего кодекса.\nч. 2. Порядок производства следственных действий в отношении лиц, имеющих статус неприкосновенности, осуществляется с учетом закона \"О статусе неприкосновенности должностных лиц штата San-Andreas\".",
