    "articleNumber": "Статья 9",
    "title": "Водителю запрещено совершать безрассудное вождение, которое выражается в:",
    "text": "а) невыполнение требования уступить дорогу во время перестроения (подрезание);\nб) несоблюдении безопасной дистанции;\nв) резком торможении, если такое торможение не требуется для предотвращения аварии;\nг) препятствовании обгону;\nд) целенаправленном нарушении нескольких положений Дорожного Кодекса подряд.\nНаказание: штраф до $10000.\n\n\nГлава II. Специальные сигналы",
