    "codeTitle": "Дорожный кодекс штата San-Andreas",
    "articleNumber": "Статья 15",
    "title": "Приближаясь к стоящему транспортному средству с включенным проблесковым маячком синего или красного цвета, водитель должен снизить скорость, чтобы иметь возможность немедленно остановиться в случае необходимости.",
    "text": "Наказание: штраф до $7000.\n\n\nГлава III. Обязанности пешехода и пассажира\n\nПешеходный переход — специальная область на проезжей части дороги, выделенная для перехода пешеходов на другую сторону улицы или дороги, либо искусственное сооружение над или под проезжей частью для тех же целей.",
    "penalty": "Наказание: штраф до $7000.",
