    "codeTitle": "Дорожный кодекс штата San-Andreas",
    "articleNumber": "Статья 16",
    "title": "Пешеходы должны двигаться по тротуару или обочине. Движение по проезжей части пешеходами запрещено.",
    "text": "Примечание: В случае отсутствия пешеходного перехода в радиусе 30 метров, пешеход может перейти дорогу, если это не будет создавать угрозу возникновения аварии.\nНаказание: штраф до $7000.",
    "penalty": "Наказание: штраф до $7000.",
