    "text": "a) В населенных пунктах движение транспортных средств разрешается со скоростью не более 100 км/ч.\nб) На автодорогах за пределами населенных пунктов разрешается ехать 120 км/ч.\nв) Если дорога за городом имеет разделительную полосу – 160 км/ч\nг) На автомагистралях допустимая скорость – 200 км/ч\nПримечание: Штрафы могут выписываться при помощи видеонаблюдения, а также сотрудниками LSPD, LSCSD, FIB.\nНаказание: штраф до $15000.",
