    "category": "Дорожный кодекс",
    "codeTitle": "Дорожный кодекс штата San-Andreas",
    "articleNumber": "Статья 36",
    "title": "Ставить транспортное средство разрешается в один ряд параллельно краю проезжей части. Двухколесные транспортные средства допускается ставить в два ряда.",
    "text": "Наказание: штраф до $5000 и эвакуация транспортного средства на штрафстоянку.",
