    "codeTitle": "Дорожный кодекс штата San-Andreas",
    "articleNumber": "Статья 38",
    "title": "Остановка запрещена на автомагистралях (хайвеях), кроме случаев чрезвычайной остановки.",
    "text": "Наказание: штраф до $9000 и эвакуация транспортного средства на штрафстоянку.\n\n\nГлава IX. Движение по автомагистралям",
    "penalty": "Наказание: штраф до $9000 и эвакуация транспортного средства на штрафстоянку.",
