    "category": "Дорожный кодекс",
    "codeTitle": "Дорожный кодекс штата San-Andreas",
    "articleNumber": "Статья 46",
    "title": "Стрелки нанесенные на дорогу для каждой полосы, указывают направления движения по полосам, с какой полосы можно совершать тот или иной маневр.",
    "text": "Наказание: штраф до $3000.",
    "penalty": "Наказание: штраф до $3000.",
