    "category": "Дорожный кодекс",
    "codeTitle": "Дорожный кодекс штата San-Andreas",
    "articleNumber": "Статья 49",
    "title": "Требуется останавливаться перед пешеходным переходом, если пешеходы пересекают дорогу:",
    "text": "а) Пешеходный переход обозначается двумя продольными параллельными линиями в пределах которых пешеходы совершают переход дороги;\nб) Пешеходный переход обозначается разметкой-зеброй по которой пешеходы совершают переход дороги.\nНаказание: штраф до $5000.",
